SELECT i_brand, i_category, SUM(ss_ext_sales_price) AS total_sales, SUM(inv_quantity_on_hand) AS total_inventory FROM inventory JOIN item ON inventory.inv_item_sk = item.i_item_sk JOIN store_sales ON store_sales.ss_item_sk = item.i_item_sk WHERE inventory.inv_date_sk = 2450829 AND store_sales.ss_sold_date_sk = 2451728 AND i_category = 'Women                                             ' GROUP BY i_brand, i_category
